1	import { loadSkills } from './skillParser';
2	export { loadSkills, parseSkill, type Skill } from './skillParser';
3	
4	// Every skills/<name>/SKILL.md, bundled with the page and sent to the app
5	// once per connection with the skills message.
6	const skillFiles = import.meta.glob('./skills/*/SKILL.md', {
7	  query: '?raw',
8	  import: 'default',
9	  eager: true,
10	}) as Record<string, string>;
11	
12	export const skills = loadSkills(skillFiles);
13	// A project skill is text for one kind of situation. The page writes each one
14	// as skills/<name>/SKILL.md: YAML frontmatter, then the body, which is the
15	// text the model gets. A skill with a `trigger` is added by the app to one
16	// request when the event it names happens; the model does not choose it. A
17	// skill with a `description` is listed for the model, which reads it with
18	// skill_read when the description fits. A skill may have both.
19	export interface Skill {
20	  name: string;
21	  trigger?: string;
22	  description?: string;
23	  text: string;
24	}
25	
26	const SKILL_NAME = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
27	const TRIGGER = /^[a-z]+(?:_[a-z]+)*$/;
28	const FRONTMATTER = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/;
29	// The app refuses a longer text (AgentHost, Protocol::kSkills).
30	export const SKILL_TEXT_LIMIT = 16 * 1024;
31	const encoder = new TextEncoder();
32	
33	function scalar(raw: string, source: string): string {
34	  if (raw.startsWith('"')) {
35	    try {
36	      const value: unknown = JSON.parse(raw);
37	      if (typeof value === 'string') return value;
38	    } catch {
39	      // Report one stable frontmatter error below.
40	    }
41	    throw new Error(`${source}: invalid quoted frontmatter value`);
42	  }
43	  if (raw.startsWith("'")) {
44	    if (!raw.endsWith("'") || raw.length < 2)
45	      throw new Error(`${source}: invalid quoted frontmatter value`);
46	    return raw.slice(1, -1).replace(/''/g, "'");
47	  }
48	  if (raw.endsWith('"') || raw.endsWith("'"))
49	    throw new Error(`${source}: invalid quoted frontmatter value`);
50	  return raw;
51	}
52	
53	export function parseSkill(text: string, source: string): Skill {
54	  const match = text.match(FRONTMATTER);
55	  if (!match) throw new Error(`${source}: SKILL.md must start with YAML frontmatter`);
56	
57	  const fields = new Map<string, string>();
58	  for (const line of match[1].split(/\r?\n/)) {
59	    const separator = line.indexOf(':');
60	    if (separator < 1) throw new Error(`${source}: invalid frontmatter line`);
61	    const key = line.slice(0, separator).trim();
62	    const raw = line.slice(separator + 1).trim();
63	    if (!['name', 'trigger', 'description'].includes(key) || fields.has(key) || !raw)
64	      throw new Error(`${source}: frontmatter must contain only name, trigger and description`);
65	    fields.set(key, scalar(raw, source));
66	  }
67	
68	  const name = fields.get('name') ?? '';
69	  const trigger = fields.get('trigger');
70	  const description = fields.get('description');
71	  const directory = source.replace(/\\/g, '/').split('/').at(-2) ?? '';
72	  if (!SKILL_NAME.test(name) || name.length > 64 || name !== directory)
73	    throw new Error(`${source}: name must match its lowercase hyphenated directory`);
74	  if (trigger === undefined && description === undefined)
75	    throw new Error(`${source}: a skill needs a trigger, a description or both`);
76	  if (trigger !== undefined && (!TRIGGER.test(trigger) || trigger.length > 64))
77	    throw new Error(`${source}: trigger must be lowercase words joined by underscores`);
78	  if (description !== undefined && (/[\r\n]/.test(description) || encoder.encode(description).length > 300))
79	    throw new Error(`${source}: description must be one line of at most 300 UTF-8 bytes`);
80	
81	  const body = text.slice(match[0].length).replace(/^(?:\r?\n)+/, '').trimEnd();
82	  if (!body) throw new Error(`${source}: skill body is empty`);
83	  if (encoder.encode(body).length > SKILL_TEXT_LIMIT)
84	    throw new Error(`${source}: skill body exceeds 16 KiB`);
85	
86	  return {
87	    name,
88	    ...(trigger === undefined ? {} : { trigger }),
89	    ...(description === undefined ? {} : { description }),
90	    text: body,
91	  };
92	}
93	
94	// Sorted by name, as the app expects them; at most one skill per trigger,
95	// since the app adds the one its event names.
96	export function loadSkills(files: Record<string, string>): Skill[] {
97	  const skills = Object.entries(files).map(([source, text]) => parseSkill(text, source));
98	  skills.sort((left, right) => left.name < right.name ? -1 : left.name > right.name ? 1 : 0);
99	  for (let index = 1; index < skills.length; index += 1)
100	    if (skills[index - 1].name === skills[index].name)
101	      throw new Error(`duplicate skill name: ${skills[index].name}`);
102	  const triggers = new Set<string>();
103	  for (const skill of skills) {
104	    if (skill.trigger === undefined) continue;
105	    if (triggers.has(skill.trigger)) throw new Error(`two skills share the trigger ${skill.trigger}`);
106	    triggers.add(skill.trigger);
107	  }
108	  return skills;
109	}
