383	// Shared with the filament and project chats (filamentInstructions.ts,
384	// projectInstructions.ts): the page draws the line the same way in all three.
385	export const CHOICES =
386	  'Answers to tap: whenever your message asks a yes-or-no question, asks the person to confirm something, or asks ' +
387	  'them to pick from a few options, its last line must be "Choices: first | second | third" -- two to four short ' +
