492	  // set up yet, and the model offered to add a printer the person already had.
493	  const alreadySetUp = 'This printer is already set up in this app: they can prepare prints for it now, connected or not.';
494	  if (session.mode === 'change')
495	    text += `\n${alreadySetUp} The person is here to say what changed on it, or to ask about it.\n`;
496	  if (session.mode === 'connect') text += `\n${alreadySetUp} The person is here to connect it.\n`;
497	  if ((context.network ?? []).length > 0)
498	    text += 'On the network now: ' + context.network!.map((found) => `${found.name} (${found.serial})`).join(', ') + '\n';
499	  const printer = context.printer;
500	  if (printer) {
501	    text += `\nThe printer this is about:\nName: ${printer.name}\n`;
502	    if (printer.stock)
503	      text +=
504	        'Kind: the settings JusPrin comes with for this model, selected in the project, not a printer the person ' +
505	        'added. Its nozzle size and connection are not saved here, and a change to its settings is saved as a copy.\n' +
506	        `Copy to save as: ${printer.copyName}\n`;
507	    if (printer.model) text += `Brand and model: ${printer.model}\n`;
508	    text += `Nozzle: ${printer.nozzle > 0 ? `${numberText(printer.nozzle)} mm` : 'unknown'}`;
509	    if (printer.nozzles.length > 0) text += ` (this model ships ${sizesText(printer.nozzles)})`;
510	    // Only a connected printer says what it holds; nothing stands in for it.
511	    text += '\nLoaded, as the printer reports it:';
512	    if (!printer.connected) text += ' not known, as it is not connected';
513	    else if (printer.spools.length === 0) text += ' nothing';
514	    for (const spool of printer.spools)
515	      text += `\n- ${spool.name || spool.material} (${spool.material}${spool.colour ? `, ${spool.colour}` : ''})`;
516	    text += `\nConnected to this app: ${printer.connected ? 'yes' : 'no'}\n`;
517	    text += `Connects through: ${printer.provider === 'bambu' ? 'Bambu Lab LAN mode' : 'Moonraker or OctoPrint'}\n`;
