519	      text +=
520	        "Bambu's network plug-in: not installed, so nothing can reach this printer yet. The app has shown the person how to " +
521	        'install it.\n';
522	  }
523	  if (context.printers) {
524	    text += '\nPrinter list (catalogId | brand and model | build volume):\n';
525	    for (const [id, name, volume] of context.printers) text += `${id} | ${name} | ${volume || '?'}\n`;
526	  }
527	  return text;
528	}
