151	// change by turning LAN Only on.
152	bool in_cloud_mode(const ConnectionCandidate& candidate)
153	{
154	    return !candidate.lan_mode && !candidate.account_only && candidate.reason.empty();
155	}
156	
157	// Why a printer is in `seen` rather than offered.
158	std::string seen_reason(const ConnectionCandidate& candidate)
159	{
160	    if (!candidate.reason.empty())
161	        return candidate.reason;
162	    return candidate.account_only ? "account_only" : "cloud_mode";
163	}
164	
165	// A printer the app knows of and does not offer, and what it knows about it.
166	std::string not_offered_text(const ConnectionCandidate& candidate)
167	{
168	    const std::string reason = seen_reason(candidate);
169	    if (reason == "account_only")
170	        return candidate.name + " is on the person's Bambu account and has not been seen on the network.";
171	    if (reason == "cloud_mode")
172	        return with_address(candidate) + " was seen on the network with LAN Only off.";
173	    if (reason == "other_model")
174	        return with_address(candidate) + " was seen on the network, but it is " +
175	               (candidate.detail.empty() ? std::string("a printer of another model") : "a " + candidate.detail) +
176	               ", not this printer's model.";
177	    if (reason == "linked_elsewhere")
178	        return with_address(candidate) + " was seen on the network, but it is already the printer \"" + candidate.detail +
179	               "\" in this app, and a device connects to one saved printer.";
180	    if (reason == "other_device")
181	        return with_address(candidate) + " was seen on the network: a printer of this model, but not the one this printer was "
182	               "set up from (" + candidate.detail + ").";
183	    if (reason == "occupied")
184	        return with_address(candidate) + " was seen on the network in LAN mode, but it reports itself bound to another account "
185	               "(occupied), so it is not offered.";
186	    throw std::logic_error("A connection candidate has a reason this conversation does not know: " + reason);
187	}
188	
189	// Only LAN mode can be connected. Every other printer the app heard of is
190	// reported apart, with the reason, so the model knows it was seen and is
191	// never told "found no printer" about one the app chose not to offer.
192	json connection_json(const PrinterConnectionInfo& info, json search)
193	{
194	    json candidates = json::array();
195	    json seen       = json::array();
196	    for (const ConnectionCandidate& candidate : info.candidates)
197	        if (offered(candidate))
198	            candidates.push_back(json{{"deviceId", candidate.id}, {"name", candidate.name}, {"address", candidate.address}});
199	        else {
200	            json entry{{"name", candidate.name}, {"address", candidate.address}, {"reason", seen_reason(candidate)}};
201	            if (!candidate.detail.empty())
202	                entry["detail"] = candidate.detail;
203	            seen.push_back(std::move(entry));
204	        }
205	    return json{{"provider", info.provider},         {"state", info.state},         {"message", info.message},
206	                {"candidates", std::move(candidates)}, {"seen", std::move(seen)},   {"search", std::move(search)},
207	                {"address", info.address},           {"hostType", info.host_type},  {"nozzleMismatch", info.nozzle_mismatch}};
208	}
