226	void PrinterConversation::start(ConversationMode mode, const std::string& printer_name)
227	{
228	    // An attempt the last session left waiting -- its panel closed meanwhile
229	    // -- is dropped before this session can read, and save, its outcome.
230	    abandon_connection();
231	    m_mode         = mode;
232	    m_printer_name = mode == ConversationMode::Add ? std::string() : printer_name;
233	    m_blocks       = json::array();
234	    m_next_block   = 1;
235	    m_opened       = false;
236	    // A new session's page writes its instructions again.
237	    m_instructions.clear();
238	    m_network.clear();
239	    m_credential_action.clear();
240	    m_credential_arguments = json::object();
241	    m_prepared.clear();
242	    m_search.reset();
243	    m_added.clear();
244	    m_needs_plugin = false;
245	    m_form.reset();
246	
247	    // The session is the one it was opened for. Its opener names a printer
248	    // it has just read -- a saved one, or for a change the stock profile the
249	    // project has selected -- so a name that finds neither is its bug.
250	    if ((m_mode == ConversationMode::Change && about().name.empty()) ||
251	        (m_mode == ConversationMode::Connect && saved(m_printer_name).name.empty()))
252	        throw std::logic_error("A printer conversation was opened for a printer that is not there: " + m_printer_name);
253	
254	    if (m_mode == ConversationMode::Add) {
255	        m_network = m_backend.network_printers();
256	        // A photo is the fastest way in, and the printers already on the
257	        // network are worth naming. Both sit under the opening, where the
258	        // person is deciding what to say.
259	        m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""}, {"kind", "tip"}});
260	        if (!m_network.empty()) {
261	            json found = json::array();
262	            for (const DiscoveredPrinter& printer : m_network)
263	                found.push_back(json{{"name", printer.name}, {"serial", printer.stable_id}, {"online", printer.connected}});
264	            m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""},
265	                                    {"kind", "network"}, {"printers", std::move(found)}});
266	        }
267	    }
268	    // Connecting a Bambu Lab printer that nothing can reach yet: the opening
269	    // says so, and the notice under it offers the plug-in.
270	    if (m_mode == ConversationMode::Connect && saved(m_printer_name).vendor_id == "BBL" &&
271	        m_backend.connection(m_printer_name).needs_network_plugin)
272	        show_plugin_needed({});
273	    m_host.session_changed();
274	}
