276	void PrinterConversation::show_plugin_needed(const std::string& message_id)
277	{
278	    m_needs_plugin = true;
279	    const bool shown = std::any_of(m_blocks.begin(), m_blocks.end(), [](const json& block) {
280	        return block.value("kind", std::string()) == "plugin" && !block.value("installed", false);
281	    });
282	    if (shown)
283	        return;
284	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id}, {"kind", "plugin"}});
285	    m_host.session_changed();
286	}
287	
288	void PrinterConversation::install_network_plugin()
289	{
290	    if (!m_needs_plugin || m_printer_name.empty())
291	        return;
292	    m_backend.install_network_plugin();
293	    // Closing the installer, or a download that failed, leaves the notice
294	    // and its button as they were; Orca's dialog has said what happened.
295	    if (m_backend.connection(m_printer_name).needs_network_plugin)
296	        return;
297	    m_needs_plugin = false;
298	    for (json& block : m_blocks)
299	        if (block.value("kind", std::string()) == "plugin")
300	            block["installed"] = true;
301	    // Discovery could not start without the plug-in; the next status check
302	    // starts it.
303	    m_prepared.clear();
304	    m_search.reset();
305	    m_host.post_note("Bambu's network plug-in is installed now, so " + m_printer_name + " can be connected.");
306	    m_host.session_changed();
307	    m_host.start_turn();
308	}
