341	json PrinterConversation::context_json() const
342	{
343	    json context = json::object();
344	    if (m_mode == ConversationMode::Add) {
345	        json printers = json::array();
346	        for (const CatalogPrinter& printer : m_backend.catalog())
347	            printers.push_back(json::array({printer.id, printer.display_name(), printer.build_volume}));
348	        json network = json::array();
349	        for (const DiscoveredPrinter& found : m_network)
350	            network.push_back(json{{"name", found.name}, {"serial", found.stable_id}});
351	        context["printers"] = std::move(printers);
352	        context["network"]  = std::move(network);
353	    }
354	    if (const SavedPrinter printer = about(); !printer.name.empty()) {
355	        context["printer"]             = printer_json(printer);
356	        context["printer"]["provider"] = printer.vendor_id == "BBL" ? "bambu" : "host";
357	        if (printer.stock) {
358	            context["printer"]["stock"]    = true;
359	            context["printer"]["copyName"] = printer.copy_name;
360	        }
361	        if (m_needs_plugin)
362	            context["printer"]["needsNetworkPlugin"] = true;
363	    }
364	    return context;
365	}
