539	Result PrinterConversation::execute_tool(ToolHandler handler, const ToolActivity& activity)
540	{
541	    const json arguments = json::parse(activity.arguments_json);
542	    switch (handler) {
543	    case ToolHandler::PrinterIdentify: return identify(arguments, activity.correlation_id);
544	    case ToolHandler::PrinterAdd: return add(arguments, activity.correlation_id);
545	    case ToolHandler::PrinterChange: return change(arguments);
546	    case ToolHandler::PrinterConnectionStatus: return connection_status(m_printer_name, activity.correlation_id);
547	    case ToolHandler::PrinterConnect: return request_credential(arguments, activity.action_id);
548	    default: return {};
549	    }
