1261	            send_attachment_updated(*record, correlation_id);
1262	    // The outgoing message is durable before any reply work starts.
1263	    m_persistence.flush();
1264	    // Sending from the composer cleared it; the draft it held is no longer
1265	    // working state to recover. A message sent from elsewhere leaves whatever
1266	    // the person was typing where it is.
1267	    if (from_composer)
1268	        m_persistence.set_draft({});
