552	std::optional<json> PrinterConversation::tool_output(const ToolActivity& activity) const
553	{
554	    const std::vector<std::string> tools = session_tools();
555	    if (std::find(tools.begin(), tools.end(), activity.tool) == tools.end())
556	        return std::nullopt;
557	    if (activity.state == Agent::ToolState::Succeeded)
558	        return json::parse(activity.result_json);
559	    if (activity.state == Agent::ToolState::Failed && activity.error)
560	        return json{{"error", json{{"code", activity.error->code}, {"message", activity.error->message}}}};
