710	Result PrinterConversation::request_credential(const json& arguments, const std::string& action_id)
711	{
712	    m_credential_action    = action_id;
713	    m_credential_arguments = arguments;
714	    m_host.session_changed();
715	    return ok(json{{"state", "credential_requested"},
716	                   {"message", "The app is waiting for the person to enter the printer credential locally."}});
717	}
