1026	
1027	    // The filament to start with: one that fits, which is installed with
1028	    // the printer; one of the person's own; one made for other printers,
1029	    // which is copied for this one; or a preset the person makes in
1030	    // OrcaSlicer's Create filament window once the printer is added.
1031	    const bool        create   = payload.value("create", false);
1032	    const std::string filament = create ? std::string() : payload.value("filament", std::string());
1033	    const auto        in       = [&filament](const std::vector<FilamentOption>& list) -> const FilamentOption* {
1034	        const auto found = std::find_if(list.begin(), list.end(), [&filament](const FilamentOption& option) { return option.name == filament; });
1035	        return found == list.end() ? nullptr : &*found;
