1037	    const FilamentOption* fitting = filament.empty() ? nullptr : in(options->filaments);
1038	    const FilamentOption* other   = filament.empty() ? nullptr : in(options->others);
1039	    const FilamentOption* own     = filament.empty() ? nullptr : in(options->own);
1040	    if (!filament.empty() && fitting == nullptr && other == nullptr && own == nullptr)
1041	        return refuse_form("That filament is no longer on the list. Choose another.");
1042	
1043	    const std::string device = payload.value("deviceId", std::string());
1044	    const auto        found  = std::find_if(m_form->nearby.begin(), m_form->nearby.end(),
1045	                                            [&device](const auto& entry) { return entry.first.stable_id == device; });
1046	    if (!device.empty() && (found == m_form->nearby.end() || found->second != id))
1047	        return refuse_form("That printer is no longer on the list. Choose it again.");
