1091	ToolExecutionCoordinator::ExtensionResult AgentHost::read_skill(const ToolActivity& activity) const
1092	{
1093	    // Only a skill on the model's list: one the page described. A skill the
1094	    // app fires on an event is not the model's to read.
1095	    ToolExecutionCoordinator::ExtensionResult result;
1096	    result.handled     = true;
1097	    const std::string name = parsed_or_object(activity.arguments_json).value("name", "");
1098	    json listed = json::array();
1099	    for (const AgentSkill& skill : m_skills) {
1100	        if (skill.description.empty())
1101	            continue;
1102	        if (skill.name == name) {
1103	            result.result_json = json{{"name", skill.name}, {"text", skill.text}}.dump();
1104	            return result;
1105	        }
1106	        listed.push_back(skill.name);
1107	    }
1108	    result.error = ToolError{"unknown_skill", "There is no skill named \"" + name + "\" on the list. Skills: " + listed.dump() + "."};
1109	    return result;
1110	}
