1112	std::optional<AgentSkillUse> AgentHost::fire_skill(const std::string& trigger, const std::string& conversation_id,
1113	                                                   const WorkspaceSnapshot& workspace) const
1114	{
1115	    // Skills are the project chat's: a session about something else has no
1116	    // workspace for them to speak of.
1117	    if (!m_session_profile.include_workspace)
1118	        return std::nullopt;
1119	    const auto skill = std::find_if(m_skills.begin(), m_skills.end(),
1120	                                    [&trigger](const AgentSkill& candidate) { return candidate.trigger == trigger; });
1121	    if (skill == m_skills.end())
1122	        return std::nullopt;
1123	    AgentSkillUse use{skill->name, skill->text, nullptr, trigger, {}};
1124	    // The file-loaded skill already asks for the presets to be checked
1125	    // against what the print is for, so a request that carries it needs no
1126	    // second skill for the same check.
1127	    if (trigger == Protocol::SkillTrigger::kSetupChanged)
1128	        use.yields_to.push_back(Protocol::SkillTrigger::kFileLoaded);
1129	    if (trigger == Protocol::SkillTrigger::kFileLoaded) {
1130	        // The plate as it stands after the load, the render view_render
1131	        // gives, so the model can see what the file holds without a call. Drawn
1132	        // now and never kept: a picture replayed on every later request
1133	        // would cost its size each time.
1134	        Workspace::RenderedImage rendered;
1135	        if (plate_has_printable_object(workspace) && m_workspace.render_view(Workspace::RenderRequest{}, rendered).succeeded())
1136	            use.picture = std::make_shared<const ToolImage>(
1137	                ToolImage{"image/png", base64_encode(rendered.png), rendered.width, rendered.height});
1138	        if (!purpose_recorded(conversation_id))
1139	            use.text += std::string("\n\n") + kNoPurposeSentence;
1140	    }
1141	    return use;
1142	}
