1146	{
1147	    std::vector<std::uint64_t> fresh;
1148	    for (const Workspace::WorkspacePlate& plate : workspace.plates)
1149	        if (plate.slice_failure && m_slice_failures_told.count(plate.slice_failure->sequence) == 0)
1150	            fresh.push_back(plate.slice_failure->sequence);
