1247	bool AgentHost::accept_user_message(ConversationMessage message, const std::string& correlation_id, bool from_composer)
1248	{
1249	    ProjectStateDocument& document        = m_persistence.document();
1250	    const std::string     conversation_id = document.active_conversation_id();
1251	    message.id    = document.allocate_message_id();
1252	    message.role  = MessageRole::User;
1253	    message.state = MessageState::Complete;
1254	    message.created_at = m_persistence.timestamp();
1255	    document.append_message(conversation_id, message, message.created_at);
1256	    // The page's staged-attachment list only drops an entry once it hears
1257	    // this back; every other place that changes an attachment's state sends
1258	    // it too.
1259	    for (const std::string& id : document.mark_attachments_sent(message.attachment_ids))
1260	        if (const std::optional<AttachmentRecord> record = document.find_attachment(id))
1261	            send_attachment_updated(*record, correlation_id);
1262	    // The outgoing message is durable before any reply work starts.
1263	    m_persistence.flush();
1264	    // Sending from the composer cleared it; the draft it held is no longer
1265	    // working state to recover. A message sent from elsewhere leaves whatever
1266	    // the person was typing where it is.
1267	    if (from_composer)
1268	        m_persistence.set_draft({});
1269	    send_envelope(Protocol::kMessageAdded, json{{"message", message_json(message)}}.dump(), correlation_id);

