205	void PrinterPanel::open(ConversationMode mode, const std::string& printer_name)
206	{
207	    // Every opening is a new session: no history carries over, so the runtime
208	    // that held the last one goes first.
209	    tear_down_runtime();
210	    m_task = Task::Printer;
211	    m_closing = false;
212	    m_after_close = {};
213	    m_conversation->start(mode, printer_name);
214	    // The page writes the opening line and asks for it to be posted once it
215	    // has loaded (printer_opening).
216	    build_runtime();
217	    Show();
218	}
