223	    m_task = Task::Filament;
224	    m_closing = false;
225	    m_after_close = {};
226	    m_filament_slot   = slot;
227	    m_filament_name   = shown;
228	    m_filament_preset = preset;
229	    m_filament_instructions.clear();
