70	void PrinterPanel::build_runtime()
71	{
72	    // Its own document, never the project's: task help is gone when the
73	    // panel closes.
74	    Agent::ProjectPersistence::Config storage;
75	    storage.in_memory = true;
76	    m_persistence     = std::make_unique<Agent::ProjectPersistence>(m_workspace, std::move(storage));
77	
78	    // Its own agent service too: one turn may be in flight per service, and
79	    // the docked panel's belongs to the project's conversation.
80	    Agent::AgentRuntime runtime = Agent::load_agent_runtime(wxGetApp().app_config);
81	    m_web_view = std::make_unique<AgentWebView>(this, m_theme, m_workspace, *m_persistence, runtime.availability,
82	                                                std::move(runtime.service), runtime.setup,
83	                                                m_task == Task::Printer ? AgentPageMode::PrinterPanel : AgentPageMode::Conversation);
84	    m_web_view->enable_chat_model_choice(wxGetApp().app_config);
85	    m_web_view->apply_appearance(m_dark);
86	    m_web_view->SetName(m_task == Task::Printer ? _L("Printer conversation") : _L("Filament conversation"));
87	    GetSizer()->Add(m_web_view.get(), 1, wxEXPAND);
88	    Layout();
89	
90	    Agent::AgentHost& host = m_web_view->host();
91	    if (m_task == Task::Printer) {
92	        host.set_session_profile(m_conversation->profile());
93	        host.set_session_state_provider([this] { return m_conversation->state_json(); });
94	        host.set_page_message_handler([this](const std::string& type, const nlohmann::json& payload) {
95	            return handle_printer_page_message(type, payload);
96	        });
97	        host.set_session_tool_executor([this](Agent::ToolHandler handler, const Agent::ToolActivity& activity) {
98	            return m_conversation->execute_tool(handler, activity);
99	        });
100	        host.set_session_tool_preflight([this](Agent::ToolHandler handler, Agent::ToolActivity& activity) {
101	            return m_conversation->preflight_tool(handler, activity);
102	        });
103	        host.set_session_tool_output([this](const Agent::ToolActivity& activity) { return m_conversation->tool_output(activity); });
104	        host.tools().set_version_callbacks(m_callbacks.version_before, m_callbacks.version_after);
105	        // Ids from this panel's own document would start again at the
106	        // first one each opening and be refused by the project's history.
107	        if (m_callbacks.allocate_action_id)
108	            host.tools().set_action_id_allocator(m_callbacks.allocate_action_id);
109	        m_settled = host.tools().subscribe([this](const Agent::ToolActivity& activity) { m_conversation->tool_settled(activity); });
110	        // The printer form is part of the page, so a page that could not
111	        // load offers OrcaSlicer's own printer list in its place.
112	        m_web_view->set_error_fallback_actions(
113	            _L("Back"), m_conversation->printer_name().empty() ? _L("Browse the full printer list") : _L("Open printer settings"),
114	            [this] { close(); },
115	            [this] {
116	                if (m_conversation->printer_name().empty())
117	                    m_conversation->handle_page_message(Agent::Protocol::kPrinterAction, {{"action", "orca_printer_list"}});
118	                else
119	                    close_to_printer_settings();
120	            });
121	    } else {
122	        // Its own instructions and the settings tools alone: the chat is
123	        // about one filament preset, not about the open project, which the
124	        // project assistant's instructions would steer it toward.
125	        host.set_session_profile(filament_profile());
126	        host.set_session_state_provider([this] { return filament_session_json(); });
127	        host.set_navigation_state_provider([this] {
128	            return nlohmann::json{{"focused", true}, {"returnLabel", m_return_label.ToStdString()}};
129	        });
130	        host.set_page_message_handler([this](const std::string& type, const nlohmann::json& payload) {
131	            return handle_filament_page_message(type, payload);
132	        });
133	        m_web_view->set_error_fallback_actions(m_return_label, _L("Open filament settings"),
134	                                               [this] { close(); }, [this] { close_to_filament_settings(); });
135	        host.set_session_tool_preflight([this](Agent::ToolHandler handler, Agent::ToolActivity& activity) {
136	            return filament_preflight(handler, activity);
137	        });
138	        // A copy saved in the preset's place takes its slot; the chat is
139	        // about the copy from then on.
140	        m_settled = host.tools().subscribe([this](const Agent::ToolActivity& activity) {
141	            if (activity.tool != "settings_apply_patch" || activity.state != Agent::ToolState::Succeeded)
142	                return;
143	            const std::string saved_as = nlohmann::json::parse(activity.result_json).value("savedAs", std::string());
144	            if (saved_as.empty() || saved_as == m_filament_preset)
145	                return;
146	            m_filament_preset = saved_as;
147	            // The page writes the instructions again for the copy.
148	            CallAfter([this] {
149	                if (m_web_view)
150	                    m_web_view->host().refresh_page_state();
151	            });
152	        });
153	        host.post_assistant_message("I can help with settings for " +
154	                                    (m_filament_name.empty() ? "the filament" : m_filament_name) +
155	                                    " in slot " + std::to_string(m_filament_slot + 1) +
156	                                    ". What would you like to change?");
157	    }
158	    m_pump.Start(kPumpIntervalMs);
159	}
