235	void PrinterPanel::close()
236	{
237	    if (m_closing)
238	        return;
239	    m_closing = true;
240	    Hide();
241	    // The runtime is closed from the page's own message handler or from a
242	    // tool its host is running, so it cannot be torn down inside a call its
243	    // own host is still on the stack for -- the trap the add-printer dialog
244	    // documented.
245	    CallAfter([this] {
246	        tear_down_runtime();
247	        if (m_callbacks.closed)
248	            m_callbacks.closed();
249	        auto after_close = std::move(m_after_close);
250	        if (after_close)
251	            after_close();
252	    });
253	}
