263	bool PrinterPanel::handle_preferences_request(const std::string& type, const nlohmann::json& payload)
264	{
265	    if (type != Agent::Protocol::kShellAction || !payload.is_object() || payload.value("action", "") != "open_preferences")
266	        return false;
267	    // The panel stays open under the window; the shell tells it when the
268	    // agent's settings changed there.
