274	bool PrinterPanel::handle_printer_page_message(const std::string& type, const nlohmann::json& payload)
275	{
276	    if (handle_preferences_request(type, payload))
277	        return true;
278	    if (type == Agent::Protocol::kPrinterAction && payload.is_object() &&
279	        payload.value("action", "") == "open_printer_settings" && !m_conversation->printer_name().empty()) {
280	        close_to_printer_settings();
281	        return true;
282	    }
283	    return m_conversation->handle_page_message(type, payload);
284	}
