286	// A filament's chat changes that filament's settings, as a printer's chat
287	// changes its printer's, and saves every change it makes: the chat is gone
288	// when the panel closes, and an unsaved edit would outlive it unexplained.
289	// Its other tools are the project assistant's.
290	std::optional<Agent::ToolError> PrinterPanel::filament_preflight(Agent::ToolHandler handler, const Agent::ToolActivity& activity) const
291	{
292	    using Agent::ToolHandler;
293	    if (handler != ToolHandler::SettingsSearch && handler != ToolHandler::SettingsGet &&
294	        handler != ToolHandler::SettingsPreviewPatch && handler != ToolHandler::SettingsApplyPatch)
295	        return std::nullopt;
296	    const nlohmann::json arguments = nlohmann::json::parse(activity.arguments_json);
297	    if (arguments.value("scope", std::string()) != "filament" ||
298	        arguments.at("target").value("preset", std::string()) != m_filament_preset)
299	        return Agent::ToolError{"not_in_this_conversation", "This chat changes the settings of one filament: pass scope filament "
300	                                                            "and target.preset \"" + m_filament_preset + "\"."};
301	    if (handler == ToolHandler::SettingsApplyPatch && !arguments.contains("persistAs"))
302	        return Agent::ToolError{"not_saved", "Every change in this chat is saved: pass persistAs \"" + m_filament_preset +
303	                                             "\", or the copy's name a read_only_preset issue gives."};
304	    return std::nullopt;
305	}
