340	bool PrinterPanel::handle_filament_page_message(const std::string& type, const nlohmann::json& payload)
341	{
342	    if (type == Agent::Protocol::kFilamentInstructions && payload.is_object()) {
343	        // Bounded: the page's words become every request's system prompt.
344	        const std::string text = payload.value("text", std::string());
345	        if (text.size() <= kFilamentInstructionsLimit && text != m_filament_instructions) {
346	            m_filament_instructions = text;
347	            m_web_view->host().set_session_profile(filament_profile());
348	        }
349	        return true;
350	    }
351	    if (handle_preferences_request(type, payload))
352	        return true;
353	    if (type != Agent::Protocol::kShellAction || !payload.is_object())
354	        return false;
355	    const std::string action = payload.value("action", "");
356	    if (action == "return_to_workspace")
357	        close();
358	    else if (action == "open_filament_settings")
359	        close_to_filament_settings();
360	    else
361	        return false;
362	    return true;
363	}
