void ProviderAgent::push_skills(const std::vector<AgentSkillUse>& skills, std::vector<RecordItem> notes)
{
    // Each fired skill's picture on the person's side, then the app's voice:
    // its notes, then every skill's text, for this request only where the
    // provider can clear it.
    for (const AgentSkillUse& skill : skills)
        if (skill.picture)
            m_transcript.items.push_back(RecordItem{RecordItem::Kind::User, {}, {kept(image_part(*skill.picture))}});
    for (RecordItem& note : notes)
        m_transcript.items.push_back(std::move(note));
    for (const AgentSkillUse& skill : skills)
        m_transcript.items.push_back(RecordItem{RecordItem::Kind::Operator, {}, {}, skill.text, {}, {}, true});
}

RecordPart ProviderAgent::kept(RecordPart part)
{
    if (const std::optional<std::string> blob = m_keep_blob(part.base64))
        part.blob = *blob;
    else
        m_unkept = true;
    return part;
}

void ProviderAgent::record()
{
    // A title request belongs to no chat: nothing it sends or gets is kept.
    if (m_kind == RequestKind::ConversationTitle || m_settled <= m_recorded)
        return;
    m_on_recorded(wire_format(m_config.profile.family),
                  std::vector<RecordItem>(m_transcript.items.begin() + m_recorded, m_transcript.items.begin() + m_settled));
    std::optional<RecordPart> image;
};

// One item of a chat's record: something the model was sent, kept as sent so
// every later request repeats it unchanged. Who speaks decides the kind:
// the person's side (their words and the app's data that travels with them:
// workspace block, file report, pictures), the operator (app notes and fired
// skills), the model (its output, thinking included, verbatim), and tool
// results, which stay in their own channel.
struct RecordItem
{
    enum class Kind { User, Operator, Assistant, Results };
    Kind                      kind{Kind::User};
    // The chat message the item came from, when it came from one.
    std::string               source;
    std::vector<RecordPart>   parts;   // User
    std::string               text;    // Operator
    nlohmann::json            output;  // Assistant: the provider's own output
    std::vector<RecordResult> results; // Results
    // Operator: a fired skill, which the model reads on the request that
    // sent it only where the provider can clear it (Anthropic's clear_at).
    bool                      clears{false};
};

// Everything one chat has sent to the model, in order, in one wire format
// ("anthropic" or "responses"). Items are only ever appended.
struct ChatRecord
{
    std::string             format;
    std::vector<RecordItem> items;

    bool holds(const std::string& message_id) const
    {
        return std::any_of(items.begin(), items.end(), [&message_id](const RecordItem& item) { return item.source == message_id; });
    }
};

