void ProviderAgent::push_skills(const std::vector<AgentSkillUse>& skills, std::vector<RecordItem> notes)
{
    // Each fired skill's picture on the person's side, then the app's voice:
    // its notes, then every skill's text, for this request only where the
    // provider can clear it.
    for (const AgentSkillUse& skill : skills)
        if (skill.picture)
            m_transcript.items.push_back(RecordItem{RecordItem::Kind::User, {}, {kept(image_part(*skill.picture))}});
    for (RecordItem& note : notes)
        m_transcript.items.push_back(std::move(note));
    for (const AgentSkillUse& skill : skills)
        m_transcript.items.push_back(RecordItem{RecordItem::Kind::Operator, {}, {}, skill.text, {}, {}, true});
}

RecordPart ProviderAgent::kept(RecordPart part)
{
    if (const std::optional<std::string> blob = m_keep_blob(part.base64))
        part.blob = *blob;
    else
        m_unkept = true;
    return part;
}

void ProviderAgent::record()
{
    // A title request belongs to no chat: nothing it sends or gets is kept.
    if (m_kind == RequestKind::ConversationTitle || m_settled <= m_recorded)
        return;
    m_on_recorded(wire_format(m_config.profile.family),
                  std::vector<RecordItem>(m_transcript.items.begin() + m_recorded, m_transcript.items.begin() + m_settled));
    std::optional<RecordPart> image;
};

// One item of a chat's record: something the model was sent, kept as sent so
// every later request repeats it unchanged. Who speaks decides the kind:
// the person's side (their words and the app's data that travels with them:
// workspace block, file report, pictures), the operator (app notes and fired
// skills), the model (its output, thinking included, verbatim), and tool
// results, which stay in their own channel.
struct RecordItem
{
    enum class Kind { User, Operator, Assistant, Results };
    Kind                      kind{Kind::User};
    // The chat message the item came from, when it came from one.
    std::string               source;
    std::vector<RecordPart>   parts;   // User
    std::string               text;    // Operator
    nlohmann::json            output;  // Assistant: the provider's own output
    std::vector<RecordResult> results; // Results
    // Operator: a fired skill, which the model reads on the request that
    // sent it only where the provider can clear it (Anthropic's clear_at).
    bool                      clears{false};
};

// Everything one chat has sent to the model, in order, in one wire format
// ("anthropic" or "responses"). Items are only ever appended.
struct ChatRecord
{
    std::string             format;
    std::vector<RecordItem> items;

    bool holds(const std::string& message_id) const
    {
        return std::any_of(items.begin(), items.end(), [&message_id](const RecordItem& item) { return item.source == message_id; });
    }
};

// Where chats' records keep the pictures and PDFs they sent, relative to the
// JusPrin data dir. Not under attachments/, which the version store prunes
// to the document's attachment index; a chat's folder goes with the chat.
inline constexpr const char* kChatRecordsDir = "chats";
inline std::string chat_record_dir(const std::string& conversation_id) { return std::string(kChatRecordsDir) + "/" + conversation_id; }

struct ConversationInfo
{
    std::string id;
    std::string title;
    std::string created_at;
    std::string updated_at;
    std::string preview;
    std::uint64_t activity_seq{0};
    if (part.kind == RecordPart::Kind::Image)
        return image_block(part.mime, part.base64);
    if (part.kind == RecordPart::Kind::Pdf)
        return json{{"type", "document"}, {"source", json{{"type", "base64"}, {"media_type", "application/pdf"}, {"data", part.base64}}}};
    return text_block(part.text);
}

// A fired skill clears only where the provider can clear it; elsewhere it
// stays in place, as on Responses.
std::vector<Message> conversation(const TurnTranscript& transcript, bool clears)
{
    std::vector<Message> messages;
    for (const RecordItem& item : transcript.items) {
        switch (item.kind) {
        case RecordItem::Kind::User: {
            json blocks = json::array();
            for (const RecordPart& part : item.parts)
                blocks.push_back(part_block(part));
            push(messages, "user", std::move(blocks));
            break;
        }
        case RecordItem::Kind::Operator: push_system(messages, item.text, item.clears && clears); break;
        case RecordItem::Kind::Assistant:
            // The response's own content, thinking included, exactly as it came.
            push(messages, "assistant", item.output);
            break;
ProviderRequest AnthropicCodec::build(const TurnTranscript& transcript, const ProviderProfile& profile, RequestKind kind) const
{
    const bool title = kind == RequestKind::ConversationTitle;
    json       messages = json::array();
    std::vector<Message> built = normalized(conversation(transcript, clears_skills(profile)));
    for (const Message& message : built)
        messages.push_back(message_json(message));
    // A breakpoint on the newest user content caches the turn so far for the
    // next request of the same turn.
    for (auto it = messages.rbegin(); it != messages.rend(); ++it)
        if ((*it)["role"] == "user") {
            (*it)["content"].back()["cache_control"] = ephemeral();
            break;
        }

    ProviderRequest request;
    if (clears_skills(profile))
        request.headers.push_back({"anthropic-beta", kClearAtBeta});
    request.body = json{{"model", profile.model},
                        {"max_tokens", profile.max_tokens},
                        {"stream", true},
                        {"system", json::array({json{{"type", "text"},
                                                     {"text", title ? std::string(kConversationTitleInstructions) : transcript.instructions},
                                                     {"cache_control", ephemeral()}}})},
                        {"messages", std::move(messages)}};
    if (!title && !transcript.tools.empty())
        request.body["tools"] = tools_json(transcript.tools);
    // The model list offers levels only for models with adaptive thinking,
    // where the level is effort and thinking stays adaptive.
    if (!title && !profile.effort.empty()) {
        request.body["thinking"]      = json{{"type", "adaptive"}};
        request.body["output_config"] = json{{"effort", profile.effort}};
    }
    // An empty system text is not accepted; the loop never builds one for a
    // reply (the page supplies the instructions), but a test may.
    if (request.body["system"][0]["text"] == "")
        request.body.erase("system");
    return request;
}

